//! Deterministic integer 2D GJK scaffold.
#![allow(dead_code)]
#[derive(Debug,Clone,Copy,Default,PartialEq,Eq)] pub struct Vec2i{pub x:i64,pub y:i64} impl Vec2i{pub fn dot(self,r:Vec2i)->i128{self.x as i128*r.x as i128+self.y as i128*r.y as i128} pub fn neg(self)->Self{Self{x:-self.x,y:-self.y}} pub fn sub(self,r:Self)->Self{Self{x:self.x-r.x,y:self.y-r.y}} pub fn triple(a:Self,b:Self,c:Self)->Self{let ac=a.dot(c);let bc=b.dot(c);Self{x:(b.x as i128*ac-a.x as i128*bc).clamp(i64::MIN as i128,i64::MAX as i128)as i64,y:(b.y as i128*ac-a.y as i128*bc).clamp(i64::MIN as i128,i64::MAX as i128)as i64}}}
pub trait ConvexShape2i{fn support(&self,dir:Vec2i)->Vec2i;} pub fn support_minkowski<A:ConvexShape2i,B:ConvexShape2i>(a:&A,b:&B,dir:Vec2i)->Vec2i{a.support(dir).sub(b.support(dir.neg()))}
#[derive(Debug,Clone,Copy)] struct Simplex{p:[Vec2i;3],len:usize} impl Simplex{fn new()->Self{Self{p:[Vec2i::default();3],len:0}} fn push(&mut self,p:Vec2i){self.p[2]=self.p[1];self.p[1]=self.p[0];self.p[0]=p;self.len=(self.len+1).min(3)}}
pub fn gjk_intersects<A:ConvexShape2i,B:ConvexShape2i>(a:&A,b:&B,initial_dir:Vec2i)->bool{let mut dir=if initial_dir.x==0&&initial_dir.y==0{Vec2i{x:1,y:0}}else{initial_dir};let mut s=Simplex::new();s.push(support_minkowski(a,b,dir));dir=s.p[0].neg();for _ in 0..32{let p=support_minkowski(a,b,dir);if p.dot(dir)<=0{return false}s.push(p);if handle(&mut s,&mut dir){return true}}false}
fn handle(s:&mut Simplex,dir:&mut Vec2i)->bool{if s.len==2{let a=s.p[0];let b=s.p[1];let ab=b.sub(a);let ao=a.neg();*dir=Vec2i::triple(ab,ao,ab);if dir.x==0&&dir.y==0{*dir=Vec2i{x:-ab.y,y:ab.x}}false}else{let a=s.p[0];let b=s.p[1];let c=s.p[2];let ab=b.sub(a);let ac=c.sub(a);let ao=a.neg();let abp=Vec2i::triple(ac,ab,ab);if abp.dot(ao)>0{s.p[2]=Vec2i::default();s.len=2;*dir=abp;return false}let acp=Vec2i::triple(ab,ac,ac);if acp.dot(ao)>0{s.p[1]=s.p[2];s.p[2]=Vec2i::default();s.len=2;*dir=acp;return false}true}}
pub struct ConvexPoly2i<'a>{pub points:&'a[Vec2i]} impl<'a> ConvexShape2i for ConvexPoly2i<'a>{fn support(&self,dir:Vec2i)->Vec2i{let mut best=self.points[0];let mut bd=best.dot(dir);for p in self.points.iter().copied().skip(1){let d=p.dot(dir);if d>bd{best=p;bd=d}}best}}
